1	#!/usr/bin/env node
2	// Build decks: node scripts/build.js [all | 06 | 06 12 ...]
3	// For each decks/NN-slug/deck.js writes deck.pptx, deck.html and notes.md, runs the
4	// series checks, then regenerates decks/manifest.md and decks/index.html.
5	
6	const fs = require("fs");
7	const path = require("path");
8	const { buildDeck } = require("../decks/_engine/kit");
9	const { renderPptx } = require("../decks/_engine/render-pptx");
10	const { renderHtml } = require("../decks/_engine/render-html");
11	const { PALETTES } = require("../decks/_engine/tokens");
12	const { writeGallery } = require("./gallery");
13	
14	const ROOT = path.join(__dirname, "..", "decks");
15	
16	function deckDirs() {
17	  return fs.readdirSync(ROOT).filter(d => /^\d\d-/.test(d) && fs.existsSync(path.join(ROOT, d, "deck.js"))).sort();
18	}
19	
20	function load(dir) {
21	  const file = path.join(ROOT, dir, "deck.js");
22	  delete require.cache[require.resolve(file)];
23	  return require(file);
24	}
25	
26	// ---- checks ------------------------------------------------------------------------
27	function lum(hex) {
28	  const c = [0, 2, 4].map(i => parseInt(hex.slice(i, i + 2), 16) / 255).map(v => (v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4));
29	  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
30	}
31	function contrast(a, b) { const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p); return (x + 0.05) / (y + 0.05); }
32	// US English: Baylor is an American department.
33	const UK = /\b(\w+(?:isation|ised|ising|ise)s?|colours?|behaviours?|centres?|centred|maths|programmes?|practise[sd]?|favour\w*|honour\w*|labour\w*|organis\w*|analys(?:e|ed|es|ing)|metres?|litres?|defence|travelled|travelling|modelling|whilst|amongst)\b/i;
34	const UK_OK = /^(exercise[sd]?|exercising|otherwise|promise[sd]?|surprise[sd]?|precise|concise|advise[sd]?|revise[sd]?|expertise|rise[s]?|raise[sd]?|arise[s]?|noise|wise|likewise|praise[sd]?|franchise|merchandise|premise[s]?|compromise[sd]?|enterprise[s]?|supervise[sd]?|disguise[sd]?|demise|improvise[sd]?|devise[sd]?|despise[sd]?|excise|comprise[sd]?|bruise[sd]?|cruise[sd]?|poise[sd]?|guise|treatise|paradise|reprise)$/i;
35	const words = s => (s.match(/[A-Za-z0-9%][^\s]*/g) || []).length;
36	
37	function check(deck) {
38	  const errs = [], warns = [];
39	  const m = deck.meta;
40	  const ids = new Set((m.sources || []).map(s => s.id));
41	  const used = new Set();
42	  let total = 0;
43	  for (const req of ["num", "slug", "title", "category", "palette", "hero", "question", "sources", "compose"]) if (m[req] == null) errs.push(`meta.${req} missing`);
44	  if (m.hero && (!m.hero.layout || !m.hero.concept)) errs.push("meta.hero needs layout and concept");
45	  deck.slides.forEach((sl, i) => {
46	    total += sl.time || 0;
47	    if (!sl.notes || words(sl.notes) < 25) errs.push(`slide ${i + 1}: talking points too thin`);
48	    sl.scene.refs.forEach(r => { used.add(r); if (!ids.has(r)) errs.push(`slide ${i + 1}: unknown source "${r}"`); });
49	    let bodyWords = 0;
50	    for (const it of sl.scene.items) {
51	      if (it.t !== "text") continue;
52	      const txt = it.runs.map(r => r.t).join("");
53	      if (!["source", "label", "figure"].includes(it.role) && !/^\s*\d{1,2}\s*$/.test(txt)) bodyWords += words(txt);
54	      const uk = txt.match(UK);
55	      if (uk && !UK_OK.test(uk[0])) errs.push(`slide ${i + 1}: British spelling "${uk[0]}" (use US English)`);
56	      for (const r of it.runs) {
57	        const col = r.color || it.color;
58	        const size = r.size || it.size;
59	        const need = size >= 24 || (size >= 18.5 && /Bold|SemiBold/.test(it.font)) ? 3 : 4.5;
60	        const cr = contrast(col, sl.scene.P.bg);
61	        if (cr < need) errs.push(`slide ${i + 1}: "${r.t.slice(0, 24)}" contrast ${cr.toFixed(2)} < ${need}`);
62	        if (size < 11) errs.push(`slide ${i + 1}: "${r.t.slice(0, 24)}" is ${size}pt, below the 11pt floor`);
63	      }
64	      if (it.x < 0 || it.y < 0 || it.x + it.w > 13.34 || it.y + it.h > 7.51) errs.push(`slide ${i + 1}: text box off the slide`);
65	    }
66	    if (bodyWords > 45) errs.push(`slide ${i + 1}: ${bodyWords} words on the slide (limit 45, aim for 35)`);
67	    else if (bodyWords > 35) warns.push(`slide ${i + 1}: ${bodyWords} words on the slide (aim for 35)`);
68	    const ukn = String(sl.notes || "").match(UK);
69	    if (ukn && !UK_OK.test(ukn[0])) warns.push(`slide ${i + 1} notes: British spelling "${ukn[0]}"`);
70	  });
71	  if (total < 255 || total > 315) errs.push(`timing totals ${total}s; target ~285s (4:45)`);
72	  ids.forEach(id => { if (!used.has(id)) warns.push(`source "${id}" listed but not cited on any slide`); });
73	  (m.sources || []).forEach(s => { if (!s.cite || s.cite.length < 30) errs.push(`source "${s.id}" needs a full citation`); });
74	  return { errs, warns, total };
75	}
76	
77	// ---- notes.md -------------------------------------------------------------------------
78	function notesMd(deck) {
79	  const m = deck.meta;
80	  const fmt = s => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
81	  let t = 0;
82	  let out = `# ${m.title}\n\n5 Slides in 5 Minutes · ${m.category} · Baylor Athletics Applied Performance\n\n`;
83	  out += `**One idea:** ${m.oneIdea || ""}\n\n**Discussion question:** ${m.question}\n\n`;
84	  out += `## Talking points\n\n`;
85	  deck.slides.forEach((sl, i) => {
86	    const refs = [...sl.scene.refs];
87	    out += `### ${i + 1}. ${sl.roleName} (${fmt(t)}–${fmt(t + (sl.time || 0))}, ~${sl.time}s)\n\n${sl.notes.trim()}\n\n`;
88	    if (refs.length) out += `_Sources on this slide: ${refs.map(r => `[${r}]`).join(", ")}_\n\n`;
89	    t += sl.time || 0;
90	  });
91	  out += `Total: about ${fmt(t)}.\n\n## Sources\n\n`;
92	  for (const s of m.sources) {
93	    out += `- **[${s.id}]** ${s.cite}${s.url ? ` <${s.url}>` : ""}${s.grade ? ` _Evidence: ${s.grade}._` : ""}${s.found ? ` _Found via: ${s.found}._` : ""}\n`;
94	    if (s.supports) out += `  - Supports: ${s.supports}\n`;
95	  }
96	  if (m.caveats) out += `\n## Caveats for the presenter\n\n${m.caveats.trim()}\n`;
97	  return out;
98	}
99	
100	// ---- manifest --------------------------------------------------------------------------
101	function writeManifest(metas) {
102	  const comp = m => (m.compose ? `${m.compose.hook} / ${m.compose.takeaway} / ${m.compose.align}` : "");
103	  const rows = metas.map(m => `| ${String(m.num).padStart(2, "0")} | ${m.title} | ${m.category} | ${m.hero.layout} | ${m.hero.concept} | ${m.palette} (${PALETTES[m.palette].name}) | ${comp(m)} |`);
104	  const pairs = new Map();
105	  const dupes = [];
106	  metas.forEach(m => {
107	    const k = `${m.hero.layout}|${m.palette}`;
108	    if (pairs.has(k)) dupes.push(`${pairs.get(k)} and ${m.num} share ${k}`);
109	    pairs.set(k, m.num);
110	  });
111	  const layouts = new Map();
112	  metas.forEach(m => { if (layouts.has(m.hero.layout)) dupes.push(`${layouts.get(m.hero.layout)} and ${m.num} share hero layout ${m.hero.layout}`); layouts.set(m.hero.layout, m.num); });
113	  const md = `# 5 Slides in 5 Minutes: deck manifest\n\nGenerated by \`scripts/build.js\`. One row per deck. The hero is the Insight slide's visual (slide 3). Uniqueness rule: no two decks share a hero layout, so no two share a hero layout + palette pair.\n\n${metas.length} decks · ${dupes.length ? `**DUPLICATES: ${dupes.join("; ")}**` : "no duplicate hero layouts or layout + palette pairs"}\n\n| # | Topic | Category | Hero layout | Hero concept | Palette | Hook / takeaway / alignment |\n|---|---|---|---|---|---|---|\n${rows.join("\n")}\n`;
114	  fs.writeFileSync(path.join(ROOT, "manifest.md"), md);
115	  return dupes;
116	}
117	
118	// ---- main ------------------------------------------------------------------------------
119	async function main() {
120	  const args = process.argv.slice(2);
121	  const all = deckDirs();
122	  const targets = !args.length || args[0] === "all" ? all : all.filter(d => args.some(a => d.startsWith(String(a).padStart(2, "0"))));
123	  let failed = 0;
124	  for (const dir of targets) {
125	    const out = path.join(ROOT, dir);
126	    try {
127	      const deck = buildDeck(load(dir));
128	      const { errs, warns, total } = check(deck);
129	      warns.forEach(w => console.log(`  warn ${dir}: ${w}`));
130	      if (errs.length) { failed++; errs.forEach(e => console.log(`  FAIL ${dir}: ${e}`)); continue; }
131	      await renderPptx(deck, path.join(out, "deck.pptx"));
132	      fs.writeFileSync(path.join(out, "deck.html"), renderHtml(deck));
133	      fs.writeFileSync(path.join(out, "notes.md"), notesMd(deck));
134	      console.log(`ok   ${dir} (${total}s)`);
135	    } catch (e) {
136	      failed++;
137	      console.log(`  FAIL ${dir}: ${e.stack.split("\n").slice(0, 3).join(" | ")}`);
138	    }
139	  }
140	  // Manifest and gallery always cover every deck on disk.
141	  const metas = [];
142	  for (const dir of all) { try { metas.push({ ...load(dir), dir }); } catch (e) { /* reported above */ } }
143	  metas.sort((a, b) => a.num - b.num);
144	  const dupes = writeManifest(metas);
145	  writeGallery(ROOT, metas);
146	  if (dupes.length) { console.log(`DUPLICATES: ${dupes.join("; ")}`); failed++; }
147	  console.log(`${targets.length - failed}/${targets.length} built · manifest ${metas.length} rows`);
148	  process.exitCode = failed ? 1 : 0;
149	}
150	
151	main();
