// Series spine drawn on every slide: running head, footer, and the 5-frame rail that
// marks where the talk stands. Identical position on all 200 slides.

const { STAGE } = require("./tokens");

function chrome(deck, index, scene) {
  const P = scene.P;
  const M = STAGE.margin;
  const items = [];
  const text = (x, y, w, h, t, o) => items.push({
    t: "text", x, y, w, h, runs: [{ t }], font: o.font, size: o.size, color: o.color,
    align: o.align || "left", valign: "middle", lineH: 1, tracking: o.tracking || 0, caps: !!o.caps, italic: false, role: "chrome",
  });

  text(M, 0.42, 5, 0.3, "5 Slides · 5 Minutes", { font: "cond", size: 11, color: P.muted, tracking: 2, caps: true });
  text(STAGE.w - M - 6.5, 0.42, 6.5, 0.3, deck.meta.title, { font: "cond", size: 11, color: P.muted, tracking: 1, caps: true, align: "right" });

  text(M, 6.86, 6, 0.3, "Baylor Athletics · Applied Performance", { font: "body", size: 11, color: P.muted });

  // Rail: five frames, current one filled with the accent.
  const fw = 0.34, gap = 0.08, fh = 0.06;
  const x0 = STAGE.w - M - (5 * fw + 4 * gap);
  for (let k = 0; k < 5; k++) {
    items.push({ t: "rect", x: x0 + k * (fw + gap), y: 6.98, w: fw, h: fh, fill: k === index ? P.accent : P.rule, line: null, lineW: 1, opacity: 1 });
  }
  return items;
}

module.exports = { chrome };
#!/usr/bin/env node
// HTML QA: node scripts/qa.js [all | 06 ...]
// Measures text overflow in the browser and screenshots each HTML slide to
// decks/NN-slug/png/html-sheet.png (all 5 slides stacked, 1280 wide; headless Chrome).

const fs = require("fs");
const path = require("path");
const { execFileSync } = require("child_process");
const { pathToFileURL } = require("url");

const CHROME = process.env.CHROME || "C:/Program Files/Google/Chrome/Application/chrome.exe";
const ROOT = path.join(__dirname, "..", "decks");
const args = process.argv.slice(2);
const dirs = fs.readdirSync(ROOT).filter(d => /^\d\d-/.test(d) && fs.existsSync(path.join(ROOT, d, "deck.html")))
  .filter(d => !args.length || args[0] === "all" || args.some(a => d.startsWith(String(a).padStart(2, "0"))));

const PROFILE = path.join(require("os").tmpdir(), `5s5m-chrome-qa-${process.pid}`);
const base = ["--headless=new", "--disable-gpu", "--hide-scrollbars", "--no-first-run", "--disable-extensions", "--no-default-browser-check", `--user-data-dir=${PROFILE}`, "--force-device-scale-factor=1", "--virtual-time-budget=1500"];
let problems = 0;
for (const d of dirs) {
  const file = path.join(ROOT, d, "deck.html");
  const url = pathToFileURL(file).href;
  // Freshness: every output must be newer than the source it came from.
  const mt = f => { try { return fs.statSync(path.join(ROOT, d, f)).mtimeMs; } catch { return 0; } };
  const stale = [];
  if (mt("deck.html") < mt("deck.js") || mt("deck.pptx") < mt("deck.js")) stale.push("deck.html/deck.pptx older than deck.js: run build.js");
  if (mt("deck.pdf") < mt("deck.pptx") || mt("png/slide5.png") < mt("deck.pptx")) stale.push("PDF/PNG renders older than deck.pptx: run export.ps1");
  if (stale.length) { problems++; stale.forEach(x => console.log(`  STALE ${d}: ${x}`)); continue; }
  const dom = execFileSync(CHROME, [...base, "--dump-dom", `${url}#qa`], { encoding: "utf8", maxBuffer: 64 << 20 });
  const m = dom.match(/<pre id="qa">([\s\S]*?)<\/pre>/);
  const found = m ? JSON.parse(m[1].replace(/&quot;/g, '"').replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")) : null;
  if (!found) { console.log(`FAIL ${d}: QA probe did not run`); problems++; continue; }
  const png = path.join(ROOT, d, "png");
  fs.mkdirSync(png, { recursive: true });
  execFileSync(CHROME, [...base, "--window-size=1280,3600", `--screenshot=${path.join(png, "html-sheet.png")}`, `${url}#sheet`], { stdio: "ignore" });
  if (found.length) { problems++; found.forEach(f => console.log(`  overflow ${d} slide ${f.slide}: "${f.text}" y+${f.overY}px x+${f.overX}px`)); }
  else console.log(`ok   ${d}`);
}
process.exitCode = problems ? 1 : 0;
# Export decks through PowerPoint: deck.pdf, png/slide1..5.png (QA renders) and thumb.png.
# Usage: pwsh -NoProfile -File scripts/export.ps1 [06 12 ...]   (no args = every deck)
param([Parameter(ValueFromRemainingArguments = $true)][string[]]$Decks)

$root = Join-Path $PSScriptRoot "..\decks" | Resolve-Path
$dirs = Get-ChildItem $root -Directory | Where-Object { $_.Name -match '^\d\d-' -and (Test-Path (Join-Path $_.FullName 'deck.pptx')) }
if ($Decks) {
  $want = @($Decks | ForEach-Object { $_ -split '[,\s]+' } | Where-Object { $_ } | ForEach-Object { $_.PadLeft(2, '0') })
  $dirs = @($dirs | Where-Object { $want -contains $_.Name.Substring(0, 2) })
}

# One PowerPoint automation at a time: parallel builders queue here.
$lock = New-Object System.Threading.Mutex($false, 'five-slides-pptx-export')
[void]$lock.WaitOne()
$app = New-Object -ComObject PowerPoint.Application
try {
  foreach ($d in $dirs) {
    $pptx = Join-Path $d.FullName 'deck.pptx'
    $pres = $app.Presentations.Open($pptx, $true, $false, $false)  # read-only, no window
    try {
      $pres.SaveAs((Join-Path $d.FullName 'deck.pdf'), 32)            # ppSaveAsPDF
      $png = Join-Path $d.FullName 'png'
      New-Item -ItemType Directory -Force $png | Out-Null
      for ($i = 1; $i -le $pres.Slides.Count; $i++) {
        $pres.Slides.Item($i).Export((Join-Path $png "slide$i.png"), 'PNG', 1600, 900)
      }
      $pres.Slides.Item(1).Export((Join-Path $d.FullName 'thumb.png'), 'PNG', 800, 450)
      Write-Output "ok   $($d.Name)"
    } finally { $pres.Close() }
  }

