input.content:
// 08 · Sleep Debt: short nights add up, people stop noticing, and weekends only partly pay it back.
// Composition: hook = small figure bottom-right in a large empty field, one-line headline top-left;
// takeaway = split columns (line | question) with a vertical rule; alignment = left.

module.exports = {
  num: 8,
  slug: "sleep-debt",
  title: "Sleep Debt",
  category: "Recovery & Load Management",
  palette: "mint",
  hero: { layout: "cumulative-ledger-steps", concept: "An illustrative week as a ledger: each short school night steps the running sleep balance lower; weekend lie-ins step it up only a little" },
  compose: { hook: "small-figure-field", takeaway: "split-columns", align: "left" },
  oneIdea: "Short nights add up, people stop noticing the cost, and a weekend of sleeping in pays back only part of it.",
  question: "Where in our calendar do athletes lose sleep several nights in a row?",
  caveats: `The core numbers come from lab studies of healthy adults, not athletes. Van Dongen et al. restricted time in bed (not measured sleep) and tested attention and reaction time, not sport performance; "up to two nights" is their phrase for the 6-hours-or-less conditions, so keep the "up to". Belenky et al.'s recovery was three nights of 8 hours in bed, not a typical weekend. Depner et al.'s weekend result is about metabolism (insulin sensitivity), not performance. Mah et al. is 11 players from one team with no control group, so present it as encouraging, not proof. The week on slide 3 is an illustration with round numbers, not data from any study. Individual sleep need varies; this deck is not a diagnosis, and anyone worried about an athlete's sleep should involve Athletic Medicine.`,
  sources: [
    { id: "vandongen2003", cite: "Van Dongen HPA, Maislin G, Mullington JM, Dinges DF. The cumulative cost of additional wakefulness: dose-response effects on neurobehavioral functions and sleep physiology from chronic sleep restriction and total sleep deprivation. Sleep. 2003;26(2):117-126. doi:10.1093/sleep/26.2.117", grade: "randomized laboratory experiment (n=48 healthy adults)", found: "external (cited across Zotero items, e.g. Mah 2011, Fullagar 2015)", supports: "14 days at 6 h or less in bed produced deficits equivalent to up to 2 nights of total sleep deprivation; sleepiness ratings rose only slightly, so subjects were largely unaware of the growing deficit." },
    { id: "belenky2003", cite: "Belenky G, Wesensten NJ, Thorne DR, Thomas ML, Sing HC, Redmond DP, et al. Patterns of performance degradation and restoration during sleep restriction and subsequent recovery: a sleep dose-response study. J Sleep Res. 2003;12(1):1-12. doi:10.1046/j.1365-2869.2003.00337.x", grade: "randomized laboratory experiment (n=66)", found: "external", supports: "After a week at 5 or 7 h in bed, three recovery nights of 8 h did not bring reaction speed back to baseline." },
    { id: "depner2019", cite: "Depner CM, Melanson EL, Eckel RH, Snell-Bergeon JK, Perreault L, Bergman BC, et al. Ad libitum weekend recovery sleep fails to prevent metabolic dysregulation during a repeating pattern of insufficient sleep and weekend recovery sleep. Curr Biol. 2019;29(6):957-967.e4. doi:10.1016/j.cub.2019.01.069", grade: "randomized laboratory experiment (n=36)", found: "external", supports: "With free weekend sleep, participants slept only about 1.1 h more than baseline in total, and insulin sensitivity still fell when short nights resumed." },
    { id: "mah2011", cite: "Mah CD, Mah KE, Kezirian EJ, Dement WC. The effects of sleep extension on the athletic performance of collegiate basketball players. Sleep. 2011;34(7):943-950. doi:10.5665/SLEEP.1132", grade: "single-team intervention without a control group (n=11)", found: "Zotero", supports: "Aiming for 10 h in bed for 5-7 weeks: faster sprint times, and free-throw and 3-point percentages up about 9 points." },
    { id: "fullagar2015", cite: "Fullagar HHK, Skorski S, Duffield R, Hammes D, Coutts AJ, Meyer T. Sleep and athletic performance: the effects of sleep loss on exercise performance, and physiological and cognitive responses to exercise. Sports Med. 2015;45(2):161-186. doi:10.1007/s40279-014-0260-0", grade: "narrative review", found: "Zotero", supports: "Athletes meet predictable sleep-compromising situations (travel, early training, competition) during a season." },
  ],
  slides: [
    {
      role: "hook", time: 45,
      notes: `Six hours a night doesn't sound like a crisis. Plenty of us, and plenty of our athletes, live there.

In a well-known lab study, people spent two weeks at six hours in bed a night. By the end, their attention and reaction times were as bad as people kept awake for up to two full nights. And here is the part that matters for us: they didn't rate themselves as much sleepier. They stopped noticing.`,
      build(s) {
        s.headline("Six hours a night adds up.", { y: 1.3, w: 9.5, h: 0.9, size: 44 });
        s.figure("2 nights", { x: 6.08, y: 3.35, w: 6.5, h: 1.75, size: 120, align: "right", refs: ["vandongen2003"] });
        s.text(5.58, 5.15, 7.0, 0.9, "Two weeks of six-hour nights cost as much attention as up to two nights awake.", { font: "light", size: 20, color: "muted", lineH: 1.2, align: "right" });
        s.source("Van Dongen et al., Sleep, 2003", { x: 4.58, w: 8.0, align: "right", refs: ["vandongen2003"] });
      },
    },
    {
      role: "problem", time: 60,
      notes: `Two problems with sleep debt.

First, you can't feel it well. In that same study, sleepiness ratings jumped after the first short night and then barely moved, while performance kept sliding. An athlete who says "I'm fine" may honestly believe it.

Second, it doesn't clear quickly. In another lab study, people who'd had a week of five or seven hours in bed got three full eight-hour nights to recover. Their reaction speed still didn't come back to where it started. A weekend lie-in is a smaller dose than that.`,
      build(s) {
        s.headline("You can't feel the debt, and it doesn't clear fast.", { y: 1.2, w: 11.6, h: 0.9, size: 44 });
        s.line(0.75, 2.75, 6.15, 2.75, { color: "rule", w: 1 });
        s.line(7.0, 2.75, 12.58, 2.75, { color: "rule", w: 1 });
        s.label("Feeling it", { x: 0.75, y: 2.95, w: 5.0 });
        s.label("Paying it back", { x: 7.0, y: 2.95, w: 5.0 });
        s.text(0.75, 3.45, 5.4, 1.9, "Sleepiness leveled off after the first short night. Performance kept falling.", { font: "light", size: 24, lineH: 1.18 });
        s.text(7.0, 3.45, 5.58, 1.9, "Three full nights of recovery didn't bring reaction speed back.", { font: "light", size: 24, lineH: 1.18 });
        s.source("Van Dongen et al. 2003", { x: 0.75, y: 5.5, w: 5.4, h: 0.3, size: 12, valign: "top", refs: ["vandongen2003"] });
        s.source("Belenky et al. 2003", { x: 7.0, y: 5.5, w: 5.4, h: 0.3, size: 12, valign: "top", refs: ["belenky2003"] });
