        s.headline("Look at the week, not the night.", { y: 1.2, w: 11.5, h: 0.9, size: 44 });
        const lines = [
          "Ask about the last few nights, not just last night.",
          "Know the weeks that take sleep: travel, exams, early lifts.",
          "Treat extra sleep as part of training.",
        ];
        lines.forEach((t, i) => s.text(0.75, 2.75 + i * 1.05, 11.6, 0.6, t, { font: "light", size: 28, lineH: 1.1 }));
        s.source("Sleep-losing situations: Fullagar et al. 2015 · Sleep extension: Mah et al. 2011", { refs: ["fullagar2015", "mah2011"] });
      },
    },
    {
      role: "takeaway", time: 50,
      notes: `The line to take away: sleep debt compounds, and weekends don't clear it.

We don't control when athletes go to bed. We do control a lot of the calendar: travel times, early sessions, how practice and class sit against each other.

Question for the room: where in our calendar do athletes lose sleep several nights in a row? Ask each unit; the answers are usually different, and that's the point.`,
      build(s) {
        s.headline("Sleep debt compounds. Weekends don't clear it.", { x: 0.75, y: 1.7, w: 5.7, h: 3.2, size: 60 });
        s.line(7.0, 1.8, 7.0, 5.9, { color: "rule", w: 1 });
        s.text(7.55, 1.8, 5.0, 3.0, "Where in our calendar do athletes lose sleep several nights in a row?", { font: "medium", size: 30, color: "accent", lineH: 1.15 });
      },
    },
  ],
};

